      },
      "derived_from": {
        "@id": "entity:target-pages_originstorypage.the_longer_answer_is_that_educational_te-v2"
      }
    },
    {
      "@id": "activity:translation-pages_originstorypage.thats_a_harder_sell_schools_are_riskaver-2026-11-25T18:26:08.379950+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-25T18:26:08.379950+00:00",
