      },
      "derived_from": {
        "@id": "entity:target-pages_originstorypage.the_paper_was_written_at_a_moment_when_3-v3"
      }
    },
    {
      "@id": "activity:translation-pages_originstorypage.if_students_follow_their_curiosity_throu-2026-11-26T01:53:29.569133+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-26T01:53:29.569133+00:00",
      "actor": {
        "@id": "agent:MICROSOFT-Azure-Cognitive-v3_(unconfigured,_pass-through)_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:target-pages_originstorypage.if_students_follow_their_curiosity_throu-v4",
      "@type": "prov:Entity",
      "prov:value": "If students follow their curiosity through real places, learning about arches, barrels, and celestial navigation because they're standing near a cathedral or a harbour, how do you assess what they've learned in a way that satisfies curriculum requirements? How do you produce the spreadsheet of numbers the principal wants while also honouring the complexity of what the student actually understood?",
      "generated_by": {
        "@id": "activity:translation-pages_originstorypage.if_students_follow_their_curiosity_throu-2026-11-26T01:53:29.569133+00:00"
