    {
      "@id": "activity:translation-pages_originstorypage.the_2007_paper_described_a_choose_your_o-2026-11-26T01:53:29.569133+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-26T01:53:29.569133+00:00",
