    {
      "@id": "activity:translation-pages_originstorypage.the_short_answer_is_that_most_of_the_ena-2026-11-26T03:40:46.474193+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-26T03:40:46.474193+00:00",
