      },
      "derived_from": {
        "@id": "entity:target-pages_originstorypage.the_longer_answer_is_that_educational_te-v5"
      }
    },
    {
      "@id": "activity:translation-pages_originstorypage.thats_a_harder_sell_schools_are_riskaver-2026-11-26T04:32:38.601694+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-26T04:32:38.601694+00:00",
      "actor": {
