      }
    },
    {
      "@id": "activity:translation-pages_originstorypage.the_document_left_that_question_open_the-2026-11-27T00:10:25.327911+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-27T00:10:25.327911+00:00",
