      }
    },
    {
      "@id": "activity:translation-pages_originstorypage.the_first_part_was_solved_by_smartphones-2026-11-27T00:10:25.327911+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-27T00:10:25.327911+00:00",
      "actor": {
