      }
    },
    {
      "@id": "activity:translation-pages_originstorypage.if_students_follow_their_curiosity_throu-2026-11-27T03:26:16.020302+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-27T03:26:16.020302+00:00",
