      },
      "derived_from": {
        "@id": "entity:target-pages_originstorypage.the_2007_paper_described_a_choose_your_o-v10"
      }
    },
    {
      "@id": "activity:translation-pages_originstorypage.peripateticware_doesnt_fully_solve_the_c-2026-11-27T03:26:16.020302+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-11-27T03:26:16.020302+00:00",
